// mTALKIE — en-têtes « setup » Vorbis des sons FMOD FSB5 (identifiés par leur CRC32), pour reconstituer des fichiers Ogg.
// Tirés de python-fsb5 (HearthSim, licence MIT, https://github.com/HearthSim/python-fsb5) : seuls ceux qu'utilisent
// Leisure Suit Larry – Wet Dreams Don't Dry et Wet Dreams Dry Twice. Tous ont deux modes (bloc court 256, bloc long 2048).
import Foundation

enum FsbVorbisHeaders {
    static let setup: [UInt32: String] = [
        1804123474: "",
        701843367: "",
        3605052372: "",
        927462883: "",
        1777296130: "",
    ]

    static func data(_ crc: UInt32) -> [UInt8]? { setup[crc].flatMap { Data(base64Encoded: $0) }.map { [UInt8]($0) } }
}
